/*
 * Modified by Actuna Sp. z o.o.:
 *   Z-08: new module - health probes /live and /ready, and the drain on
 *   shutdown (shutdownTimeout, preShutdown hook)
 *   Z-16: health.unreadyGrace - the time /ready answers 503 before the flows
 *   stop on a shutdown (and, in flows/reload.js, before a reload from storage)
 * This notice is required by section 4(b) of the Apache License 2.0.
 */

/**
 * Health probes and the drain on shutdown (Z-08).
 *
 * Settings:
 *  - `health: { enabled: false, path: "/health", port, host }` - with `enabled`
 *    the probes `<path>/live` and `<path>/ready` answer without authentication.
 *    Without `port` (or with `port` equal to `uiPort`) they are mounted on the
 *    main server before any authentication (by the CLI or an embedding
 *    application, with `handler`); with `port` this module starts its own
 *    server on `host` (default `uiHost`).
 *  - `shutdownTimeout` (ms, not set by default): the longest drain on shutdown.
 *    Without it there is no drain and the `preShutdown` hook is not called
 *    (R-22, R-37).
 *  - `health.unreadyGrace` (ms, not set by default, needs `health.enabled`):
 *    the least time `/ready` answers 503 before the flows stop for a planned
 *    stop (a stop signal here, a reload from storage in flows/reload.js), so a
 *    load balancer that polls `/ready` stops sending traffic first. The wait
 *    runs in parallel with the hooks and is counted inside `shutdownTimeout`
 *    (and `deploy.reload.preReloadTimeout`). An editor deployment is not affected.
 *
 * Responses (no I/O, the instance state is read from runtime/lib/state.js):
 *  - `/live`: 200 `{"status":"ok"}` in every state
 *  - `/ready`: 200 `{"status":"ok"}` when the instance is ready (`ready`,
 *    `loaded`, `reloadPending` before draining when it was ready), otherwise
 *    503 with the constant body `{"status":"unavailable"}` (R-22)
 *  - other methods: 405; other paths under `<path>`: 404
 *  - always `Content-Type: application/json` and `Cache-Control: no-store`
 * @module
 */

const http = require("http");
const { log, hooks } = require("@node-red/util");
const instanceState = require("./state");

const DEFAULT_PATH = "/health";
const BODY_OK = '{"status":"ok"}';
const BODY_UNAVAILABLE = '{"status":"unavailable"}';
const BODY_NOT_FOUND = '{"status":"not_found"}';
const BODY_NOT_ALLOWED = '{"status":"method_not_allowed"}';

const NO_GRACE = Object.freeze({ ms: 0 });

let settings = {};
let server = null;
// The running shutdown: {promise, cancelDrain} or null
let shutdownState = null;

/**
 * @param {Object} userSettings - the runtime settings (`health`, `shutdownTimeout`,
 *     `uiPort`, `uiHost`, `httpAdminRoot`, `httpNodeRoot`)
 */
function init(userSettings) {
    settings = userSettings || {};
    shutdownState = null;
    const grace = resolveUnreadyGrace(settings);
    if (grace.problem === "invalid") {
        log.warn(log._("health.invalid-unready-grace", { value: String(getHealthSettings().unreadyGrace) }));
    } else if (grace.problem === "no-probes") {
        log.warn(log._("health.unready-grace-without-probes"));
    }
}

function getHealthSettings() {
    return (settings.health && typeof settings.health === "object") ? settings.health : {};
}

/**
 * Reads `health.unreadyGrace` (Z-16): a finite number > 0 (ms) with
 * `health.enabled: true`. No logging - `init` warns about a problem once.
 * @param {Object} userSettings - the runtime settings
 * @return {{ms: number, problem: (undefined|"invalid"|"no-probes")}} `ms` is 0 (off)
 *     when the setting is not set or has a problem
 */
function resolveUnreadyGrace(userSettings) {
    const h = (userSettings && userSettings.health && typeof userSettings.health === "object") ? userSettings.health : {};
    const value = h.unreadyGrace;
    if (value === undefined || value === null) {
        return NO_GRACE;
    }
    if (typeof value !== "number" || !isFinite(value) || value < 0) {
        return { ms: 0, problem: "invalid" };
    }
    if (value === 0) {
        return NO_GRACE;
    }
    if (h.enabled !== true) {
        return { ms: 0, problem: "no-probes" };
    }
    return { ms: value };
}

/**
 * @return {boolean} whether the health probes are enabled (`health.enabled: true`)
 */
function isEnabled() {
    return getHealthSettings().enabled === true;
}

/**
 * @return {string} the base path of the probes, without a trailing slash
 */
function getPath() {
    let p = getHealthSettings().path;
    if (p === undefined || p === null) {
        p = DEFAULT_PATH;
    }
    p = String(p);
    if (p.length > 1 && p.slice(-1) === "/") {
        p = p.replace(/\/+$/, "");
    }
    return p;
}

function hasOwnPort() {
    const port = getHealthSettings().port;
    return port !== undefined && port !== null && port !== "" && !(settings.uiPort !== undefined && Number(port) === Number(settings.uiPort));
}

/**
 * @return {boolean} whether the probes are enabled and served by the main
 *     server (no own `health.port`) - the CLI mounts `handler` then
 */
function usesMainServer() {
    return isEnabled() && !hasOwnPort();
}

function send(req, res, status, body, extraHeaders) {
    res.statusCode = status;
    res.setHeader("Content-Type", "application/json; charset=utf-8");
    res.setHeader("Cache-Control", "no-store");
    res.setHeader("Content-Length", Buffer.byteLength(body));
    if (extraHeaders) {
        Object.keys(extraHeaders).forEach(function(h) { res.setHeader(h, extraHeaders[h]) });
    }
    res.end(req.method === "HEAD" ? undefined : body);
}

function respond(req, res, subPath) {
    subPath = (subPath || "/").split("?")[0];
    if (subPath !== "/live" && subPath !== "/ready") {
        return send(req, res, 404, BODY_NOT_FOUND);
    }
    if (req.method !== "GET" && req.method !== "HEAD") {
        return send(req, res, 405, BODY_NOT_ALLOWED, { "Allow": "GET, HEAD" });
    }
    if (subPath === "/live") {
        return send(req, res, 200, BODY_OK);
    }
    if (instanceState.isReady()) {
        return send(req, res, 200, BODY_OK);
    }
    return send(req, res, 503, BODY_UNAVAILABLE);
}

/**
 * The request handler of the probes, mounted at the probe path
 * (`app.use(health.path, handler)`): `req.url` is relative to the path. It does
 * not call `next` - every request under the path is answered.
 * @param {IncomingMessage} req
 * @param {ServerResponse} res
 */
function handler(req, res) {
    respond(req, res, req.url);
}

// The handler of the own server: the full url
function serverHandler(req, res) {
    const base = getPath();
    const url = req.url || "/";
    if (url === base || url.startsWith(base + "/") || url.startsWith(base + "?")) {
        return respond(req, res, url.slice(base.length) || "/");
    }
    return send(req, res, 404, BODY_NOT_FOUND);
}

function healthError(code, message) {
    const err = new Error(message);
    err.code = code;
    return err;
}

/**
 * Starts the probes: validates the settings, logs shadowed routes and starts
 * the own server when `health.port` is set. Called at the beginning of
 * `runtime.start()`, so the probes answer from the state "starting".
 * @return {Promise} rejects with `health.invalid-path` or `health.port-in-use`
 */
function start() {
    if (!isEnabled()) {
        return Promise.resolve();
    }
    const base = getPath();
    if (!base || base[0] !== "/" || base === "/") {
        return Promise.reject(healthError("health.invalid-path", log._("health.invalid-path", { path: String(getHealthSettings().path) })));
    }
    ["httpAdminRoot", "httpNodeRoot"].forEach(function(rootSetting) {
        const root = settings[rootSetting];
        if (typeof root === "string" && root !== "" && (base + "/").startsWith(root.slice(-1) === "/" ? root : root + "/")) {
            log.info(log._("health.path-shadows-route", { path: base, setting: rootSetting }));
        }
    });
    const healthSettings = getHealthSettings();
    if (healthSettings.port !== undefined && healthSettings.port !== null && !hasOwnPort()) {
        log.warn(log._("health.port-is-ui-port", { port: healthSettings.port }));
    }
    if (!hasOwnPort()) {
        return Promise.resolve();
    }
    const port = healthSettings.port;
    const host = healthSettings.host || settings.uiHost;
    return new Promise(function(resolve, reject) {
        const srv = http.createServer(serverHandler);
        const onError = function(err) {
            srv.removeListener("listening", onListening);
            if (err.code === "EADDRINUSE") {
                reject(healthError("health.port-in-use", log._("health.port-in-use", { port: port })));
            } else {
                reject(err);
            }
        };
        const onListening = function() {
            srv.removeListener("error", onError);
            srv.on("error", function(err) {
                log.error(log._("health.server-error", { message: err.message }));
            });
            server = srv;
            log.info(log._("health.listening", { port: srv.address().port, path: base }));
            resolve();
        };
        srv.once("error", onError);
        srv.once("listening", onListening);
        srv.listen(port, host);
    });
}

/**
 * @return {http.Server|null} the own server of the probes (with `health.port`)
 */
function getServer() {
    return server;
}

/**
 * Closes a server: no new connections, idle connections closed; resolves when
 * the server closed or at the latest after `limit` ms (active requests may
 * still finish until the process exits). Used for the own server and by the
 * CLI for the main server after `RED.stop()` (D-05, only with `health.enabled` - R-22).
 * @param {http.Server} srv
 * @param {number} [limit=5000]
 * @return {Promise}
 */
function closeServer(srv, limit) {
    if (!srv || !srv.listening) {
        return Promise.resolve();
    }
    limit = limit > 0 ? limit : 5000;
    return new Promise(function(resolve) {
        const timer = setTimeout(resolve, limit);
        if (timer.unref) {
            timer.unref();
        }
        srv.close(function() {
            clearTimeout(timer);
            resolve();
        });
        if (typeof srv.closeIdleConnections === "function") {
            srv.closeIdleConnections();
        }
    });
}

/**
 * Stops the own server of the probes (after the runtime stopped).
 * @return {Promise}
 */
function stop() {
    const srv = server;
    server = null;
    return closeServer(srv, 1000);
}

function getShutdownTimeout() {
    const t = settings.shutdownTimeout;
    return (typeof t === "number" && t > 0) ? t : 0;
}

/**
 * Shuts the runtime down with a drain (contract E-01 part C, D-11):
 *
 *  1. instance state "stopping" (`/ready` 503, `/live` 200) - synchronously
 *  2. only with `shutdownTimeout` and registered handlers: the `preShutdown`
 *     hook with `{reason, deadline, signal}`, waited for at most
 *     `shutdownTimeout` (a timeout logs a warning, a failure an error - the
 *     shutdown goes on); without `shutdownTimeout` the hook is not called (R-37)
 *  3. `stop(reason)` - `RED.stop(reason)` (R-23)
 *
 * A second call during the drain (a second signal) ends the drain at once
 * (R-22); a call after the drain returns the same promise. Closing the HTTP
 * server is left to the caller (the CLI closes its server only with
 * `health.enabled` - R-22).
 * @param {Object} opts
 * @param {string} [opts.reason="shutdown"] - for example "SIGTERM"
 * @param {string} [opts.signal] - the signal, when the shutdown comes from one
 * @param {function(string): Promise} opts.stop - stops the runtime (`RED.stop`)
 * @return {Promise} resolves when `stop` resolved
 */
function shutdown(opts) {
    opts = opts || {};
    if (shutdownState) {
        if (shutdownState.cancelDrain) {
            shutdownState.cancelDrain();
        }
        return shutdownState.promise;
    }
    const reason = (typeof opts.reason === "string" && opts.reason) ? opts.reason : "shutdown";
    const current = shutdownState = { cancelDrain: null, promise: null };
    instanceState.markStopping(reason);
    const timeout = getShutdownTimeout();
    // Z-16: /ready has answered 503 since markStopping() above; the grace is
    // counted inside shutdownTimeout when it is set
    let grace = resolveUnreadyGrace(settings).ms;
    if (grace && timeout && grace > timeout) {
        grace = timeout;
    }
    const withHook = !!(timeout && hooks.has("preShutdown"));
    let drained = Promise.resolve();
    if (withHook || grace) {
        if (withHook) {
            log.info(log._("health.draining", { timeout: timeout }));
        }
        if (grace) {
            log.info(log._("health.unready-grace", { grace: grace }));
        }
        const deadline = Date.now() + timeout;
        drained = new Promise(function(resolve) {
            let finished = false;
            let parts = 0;
            const timers = [];
            // The drain ends when every part ended (the hook, the grace) or at once
            // when cancelled (a second signal)
            const finish = function() {
                if (!finished) {
                    finished = true;
                    timers.forEach(clearTimeout);
                    current.cancelDrain = null;
                    resolve();
                }
            };
            const partDone = function() {
                parts--;
                if (parts === 0) {
                    finish();
                }
            };
            current.cancelDrain = finish;
            if (grace) {
                parts++;
                timers.push(setTimeout(partDone, grace));
            }
            if (withHook) {
                parts++;
                let hookEnded = false;
                const hookDone = function() {
                    if (!hookEnded) {
                        hookEnded = true;
                        partDone();
                    }
                };
                timers.push(setTimeout(function() {
                    if (!hookEnded && !finished) {
                        log.warn(log._("health.shutdown-timeout", { timeout: timeout }));
                    }
                    hookDone();
                }, timeout));
                hooks.trigger("preShutdown", { reason: reason, deadline: deadline, signal: opts.signal }).then(hookDone, function(err) {
                    if (!hookEnded && !finished) {
                        log.error(log._("health.shutdown-hook-failed", { message: (err && err.message) || String(err) }));
                    }
                    hookDone();
                });
            }
        });
    }
    current.promise = drained.then(function() {
        return opts.stop(reason);
    });
    return current.promise;
}

module.exports = {
    init,
    isEnabled,
    getPath,
    usesMainServer,
    handler,
    start,
    stop,
    getServer,
    closeServer,
    shutdown,
    resolveUnreadyGrace
};
